from typing import List
import heapq


class Solution:
    def minOperations(self, n: int, m: int) -> int:
        length = len(str(n))
        limit = 10**length
        low = 10 ** (length - 1) if length > 1 else 0
        is_prime = [True] * limit
        is_prime[0] = False
        is_prime[1] = False
        for i in range(2, int(limit**0.5) + 1):
            if is_prime[i]:
                for j in range(i * i, limit, i):
                    is_prime[j] = False
        if is_prime[n] or is_prime[m]:
            return -1
        dist = [float("inf")] * limit
        dist[n] = n
        heap = [(n, n)]
        while heap:
            cost, cur = heapq.heappop(heap)
            if cur == m:
                return cost
            if cost > dist[cur]:
                continue
            place = 1
            for _ in range(length):
                digit = cur // place % 10
                candidates = []
                if digit < 9:
                    candidates.append(cur + place)
                if digit > 0:
                    candidates.append(cur - place)
                for nxt in candidates:
                    if nxt >= low and not is_prime[nxt] and cost + nxt < dist[nxt]:
                        dist[nxt] = cost + nxt
                        heapq.heappush(heap, (cost + nxt, nxt))
                place *= 10
        return -1

